            const rendered = renderTokensToHtml('きょうはよむ', tokens, DEFAULT_SETTINGS);
            document.body.innerHTML = rendered;
            const renderedWords = Array.from(document.querySelectorAll<HTMLElement>('.jpdb-reader-word'));
