        const [phraseTimed] = parseSubtitleText('WEBVTT\n\n00:00:01.000 --> 00:00:04.000\n<00:00:01.500>bottom line <00:00:02.500>Okay\n');

        expect(plain.wordTimingsExact).toBe(false);
        expect(plain.words).toBeUndefined();
